+    // F-C4-576 (W8, 4APP4 Coder-4) — java.util.AbstractMap$SimpleEntry /
+    // $SimpleImmutableEntry FULL ENTRY LAW.
+    //
+    // OpenJDK (java/util/AbstractMap.java: JDK 8..21, unchanged):
+    //   SimpleImmutableEntry(K key, V value) — stores the pair;
+    //   getKey() → key;  getValue() → value;
+    //   setValue(V) → UnsupportedOperationException (immutable variant);
+    //   toString() → key + "=" + value;
