+            f576_recv_match =
+                rc == "Ljava/util/AbstractMap$SimpleImmutableEntry;" ||
+                rc == "Ljava/util/AbstractMap$SimpleEntry;";
+        }
+        if (f576_recv_match &&
+            (method == "<init>" || method == "getKey" || method == "getValue" ||
+             method == "setValue" || method == "toString" ||
+             method == "equals" || method == "hashCode")) {
+        const bool f576_immutable =
+            class_name != "Ljava/util/AbstractMap$SimpleEntry;" &&
