+            else if (!kv.is_null && kv.type == DalvikType::OBJECT_REF) ks = "obj";
+            if (!vv.is_null && vv.type == DalvikType::STRING_REF) vs = vv.string_val;
+            else if (!vv.is_null && vv.type == DalvikType::OBJECT_REF) vs = "obj";
+            result = DalvikValue::make_string(ks + "=" + vs, 0);
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        if (method == "hashCode") {
+            // OpenJDK: entryHash(key) ^ entryHash(value), 0 for null.
+            int32_t kh = 0, vh = 0;
+            DalvikValue kv = f576_key(), vv = f576_val();
+            if (!kv.is_null && kv.type == DalvikType::INT32) kh = kv.int_val;
+            if (!vv.is_null && vv.type == DalvikType::INT32) vh = vv.int_val;
+            result = DalvikValue::make_int(kh ^ vh);
+            status = ApiCallTrace::Status::IMPLEMENTED;
+            return true;
+        }
+        // equals: identity fast path + field compare via the heap pair.
+        if (method == "equals") {
