+                               ok2->string_val == kv.string_val;
+                    bool veq = ov2.has_value() &&
+                               ov2->type == vv.type &&
+                               ov2->object_id == vv.object_id &&
+                               ov2->string_val == vv.string_val;
+                    eq = keq && veq;
